     3	/// Builds prompt-biasing strings from the user's custom vocabulary (names,
     4	/// jargon, acronyms). Whisper steers its spelling toward terms that appear in
     5	/// its `prompt`, and the cleanup LLM uses the same list as a spelling guide.
     6	///
     7	/// Two deliberate choices, both backed by the prompting guidance:
     8	///  - Sentence-style framing ("…may include these terms: …") biases more
     9	///    reliably than a bare comma list.
    10	///  - Whisper only honors roughly the final 224 prompt tokens, so the term
    11	///    list is capped to a conservative character budget that leaves room for
    12	///    the framing sentence.
    13	public enum VocabularyPrompt {
    14	    /// ~224 Whisper tokens ≈ 800 chars; we stay well under so the framing
    15	    /// sentence is never the part that gets truncated away.
    16	    static let maxTermCharacters = 600
    17	
    18	    /// The cleanup LLM's system prompt has no 224-token ceiling, so the full
    19	    /// built-in list plus a large personal list fit (~1750 + ~1050 chars on
    20	    /// this machine). Still bounded so a huge config can't inflate every
    21	    /// cleanup request or drown the 8B model's core rules. ~3000 chars ≈ 750
    22	    /// tokens, ~4× the base prompt.
    23	    static let maxCleanupTermCharacters = 3000
    24	
    25	    /// Trimmed, case-insensitively de-duplicated, order-preserving term list.
    26	    public static func normalize(_ terms: [String]) -> [String] {
    27	        var seen = Set<String>()
    28	        var out: [String] = []
    29	        for raw in terms {
    30	            let term = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    31	            guard !term.isEmpty else { continue }
    32	            if seen.insert(term.lowercased()).inserted { out.append(term) }
    33	        }
    34	        return out
    35	    }
    36	
    37	    /// Sentence-style initial prompt for Whisper's `/inference`, or nil when
    38	    /// there's nothing to bias.
    39	    public static func whisperPrompt(_ terms: [String]) -> String? {
    40	        guard let list = cappedList(terms, budget: maxTermCharacters) else { return nil }
    41	        return "The transcript may include these terms: \(list)."
    42	    }
    43	
    44	    /// A rule appended to the cleanup system prompt so the LLM preserves and
    45	    /// fixes near-miss spellings of the user's terms. Nil when empty.
    46	    public static func cleanupRule(_ terms: [String]) -> String? {
    47	        guard let list = cappedList(terms, budget: maxCleanupTermCharacters) else { return nil }
    48	        return "- Preserve and correctly spell these terms when they appear; "
    49	            + "fix obvious near-miss misspellings of them: \(list)."
    50	    }
    51	
    52	    /// Normalized terms joined with ", ", truncated to the character budget.
    53	    /// Nil when no terms survive normalization.
    54	    private static func cappedList(_ terms: [String], budget: Int) -> String? {
    55	        let normalized = normalize(terms)
    56	        guard !normalized.isEmpty else { return nil }
    57	        var included: [String] = []
    58	        var length = 0
    59	        for term in normalized {
    60	            let added = term.count + (included.isEmpty ? 0 : 2) // ", " separator
    61	            if !included.isEmpty, length + added > budget { break }
    62	            included.append(term)
    63	            length += added
    64	        }
    65	        return included.joined(separator: ", ")
    66	    }
